#include "services/project_references.h"
#include "protocol/lsp_wire.h"
#include <xrt.h>
#include <stdio.h>
#include <string.h>
static unsigned checks;
static xide_project_reference_stats lastStats;
#define CHECK(v) do{++checks;if(!(v)){fprintf(stderr,"project_references_test:%d:%s\n",__LINE__,#v);return 0;}}while(0)
static int writeText(const char* path,const char* text){return xrtFileWriteAtomic(path,(xbytesview){(const unsigned char*)text,strlen(text)});}
static int query(xide_project_references* store,xls_context* scope,const xls_analysis_document* docs,size_t count,int include,size_t wanted,size_t built,size_t reused)
{
 const char* at=strstr(xlsTextData(docs[0].text),"compute(7)");int line,character;CHECK(at && xideLspOffsetToPosition(xlsTextData(docs[0].text),(int)(at-xlsTextData(docs[0].text)),&line,&character));xide_reference_query* q=xideProjectReferencesSubmit(store,scope,docs,count,docs[0].key,docs[0].path,line,character,include);CHECK(q);xide_project_reference_stats stats;const xvalue* result=NULL;char error[512]={0};enum xide_reference_query_state state;
 for(unsigned i=0;;++i){state=xideProjectReferencesResult(q,&result,&stats,error,sizeof(error));if(state!=XIDE_REFERENCES_PENDING)break;if(i>=3000){CHECK(0);}xrtSleep(1);}
 if(state!=XIDE_REFERENCES_READY)fprintf(stderr,"project references error: %s\n",error);
 CHECK(state==XIDE_REFERENCES_READY && result && xrtValueCount(result)==wanted);CHECK(stats.locations==wanted && stats.captured==built && stats.reused==reused && stats.thread!=xrtThreadCurrentId());CHECK(stats.roots==built+reused && stats.records<=65538 && stats.chargedBytes<=128u*1024u*1024u);lastStats=stats;xvalue* taken=xideProjectReferencesTake(q);CHECK(taken && !xideProjectReferencesTake(q));xideProjectReferencesQueryDestroy(q);CHECK(xrtValueCount(taken)==wanted);xrtValueRelease(taken);return 1;
}
static int run(void)
{
 char* directory=xrtPathAbs("build/project-references");CHECK(directory && xrtDirCreateAll(directory));char *entry=xrtPathJoin(directory,"main.xl"),*other=xrtPathJoin(directory,"未打开.xl"),*shared=xrtPathJoin(directory,"shared.xl"),*shadow=xrtPathJoin(directory,"shadow.xl"),*extra=xrtPathJoin(directory,"unused.xl"),*project=xrtPathJoin(directory,"project.xlp"),*compiler=xrtPathJoin(directory,"absent-xl.exe");CHECK(entry && other && shared && shadow && extra && project && compiler);
 const char* mainText="\xef\xbb\xbf" "import shared\r\nfunc main(...) as int\r\n return shared.compute(7)\r\nend\r\n";const char* otherText="import shared\nfunc main(...) as int\n return shared.compute(8)+shared.compute(9)\nend\n";const char* edited="import shared\nfunc main(...) as int\n return shared.compute(8)+shared.compute(9)+shared.compute(10)\nend\n";const char* one="import shared\nfunc main(...) as int\n return shared.compute(8)\nend\n";const char* body="export func compute(int value) as int\n return value+1\nend\n";const char* changed="export func compute(int value) as int\n return value+2\nend\n";
 CHECK(writeText(entry,mainText) && writeText(other,otherText) && writeText(shared,body) && writeText(shadow,"func compute(int value) as int\n return value\nend\nfunc main(...) as int\n return compute(7)\nend\n"));const char* members[]={entry,other,shared,shadow,entry};xls_context_spec spec={.kind=XLS_CONTEXT_PROJECT,.project=project,.configuration="debug",.entry=entry,.directory=directory,.analysisProfile="xlang-ls/compiler-xrt-v1",.targetKind="exe"};spec.lists[XLS_CONTEXT_MEMBERS]=(xls_context_strings){members,5};xls_context* scope=xlsContextCreate(&spec,16u*1024u*1024u,NULL);xide_toolchains* cache=xideToolchainsCreate();xide_project_references* store=xideProjectReferencesCreate(cache,compiler,NULL);CHECK(scope && cache && store);xls_text* text=xlsTextCreate(mainText,strlen(mainText),strlen(mainText),NULL);xls_analysis_document docs[3]={{"entry",entry,text,1,1}};CHECK(text);
 CHECK(query(store,scope,docs,1,1,4,4,0));CHECK(query(store,scope,docs,1,0,3,1,3));
 CHECK(writeText(other,edited) && query(store,scope,docs,1,1,5,2,2));
 xls_text* dirty=xlsTextCreate(one,strlen(one),strlen(one),NULL);CHECK(dirty);docs[1]=(xls_analysis_document){"other",other,dirty,2,1};CHECK(query(store,scope,docs,2,1,3,2,2));
 xls_text* unused=xlsTextCreate("broken unused",13,13,NULL);CHECK(unused);docs[2]=(xls_analysis_document){"unused",extra,unused,3,1};CHECK(query(store,scope,docs,3,1,3,1,3));CHECK(query(store,scope,docs,2,1,3,1,3));CHECK(query(store,scope,docs,1,1,5,2,2));
 CHECK(writeText(shared,changed) && query(store,scope,docs,1,1,5,3,1));
 const char* fewer[]={entry,shared,shadow};spec.lists[XLS_CONTEXT_MEMBERS]=(xls_context_strings){fewer,3};xls_context* reduced=xlsContextCreate(&spec,16u*1024u*1024u,NULL);CHECK(reduced && query(store,reduced,docs,1,1,2,3,0));xlsContextRelease(reduced);
 CHECK(writeText(other,"func main(\n"));xide_reference_query* failed=xideProjectReferencesSubmit(store,scope,docs,1,"entry",entry,2,17,1);CHECK(failed);enum xide_reference_query_state state;const xvalue* result=NULL;for(unsigned i=0;;++i){state=xideProjectReferencesResult(failed,&result,NULL,NULL,0);if(state!=XIDE_REFERENCES_PENDING)break;if(i>=3000){CHECK(0);}xrtSleep(1);}CHECK(state==XIDE_REFERENCES_FAILED && !result && !xideProjectReferencesTake(failed));xideProjectReferencesQueryDestroy(failed);CHECK(writeText(other,edited) && query(store,scope,docs,1,1,5,2,2));
 char* widePaths[40];const char* wideMembers[45];for(size_t i=0;i<5;++i)wideMembers[i]=members[i];for(unsigned i=0;i<40;++i){char name[32];snprintf(name,sizeof(name),"member-%u.xl",i);widePaths[i]=xrtPathJoin(directory,name);wideMembers[5+i]=widePaths[i];CHECK(widePaths[i] && writeText(widePaths[i],one));}spec.lists[XLS_CONTEXT_MEMBERS]=(xls_context_strings){wideMembers,45};xls_context* wide=xlsContextCreate(&spec,16u*1024u*1024u,NULL);CHECK(wide && query(store,wide,docs,1,1,45,44,0));xide_project_reference_stats cold=lastStats;CHECK(query(store,wide,docs,1,1,45,1,43));CHECK(lastStats.keyActorBuilds==cold.keyActorBuilds && lastStats.keyActorHits>cold.keyActorHits && lastStats.keyActorSessions<=2 && lastStats.keyNavigationHits==1 && !lastStats.keyNavigationBuilds);xlsContextRelease(wide);for(size_t i=0;i<40;++i)xrtFree(widePaths[i]);
 CHECK(!xideProjectReferencesSubmit(store,scope,docs,1,"entry",entry,0,0,2));CHECK(!xideProjectReferencesSubmit(store,NULL,docs,1,"entry",entry,0,0,1));
 xide_reference_query* queued[40]={0};size_t accepted=0,rejected=0;for(size_t i=0;i<40;++i){queued[i]=xideProjectReferencesSubmit(store,scope,docs,1,"entry",entry,2,17,1);if(queued[i])++accepted;else ++rejected;}CHECK(accepted && rejected);for(size_t i=0;i<40;++i){xideProjectReferencesCancel(queued[i]);xideProjectReferencesQueryDestroy(queued[i]);}
 xideProjectReferencesDestroy(store);xideToolchainsDestroy(cache);xlsContextRelease(scope);xlsTextRelease(text);xlsTextRelease(dirty);xlsTextRelease(unused);xrtFree(entry);xrtFree(other);xrtFree(shared);xrtFree(shadow);xrtFree(extra);xrtFree(project);xrtFree(compiler);xrtFree(directory);return 1;
}
int main(void){if(!run())return 1;printf("project_references_test passed: %u checks;all configured roots/unopened members,dedup/shadowing,exact source/cache/overlay/configuration changes,failure recovery,bounded queue and cancellation teardown\n",checks);return 0;}

